1	#include "runner/push_overlap.h"
2	
3	#include <stdlib.h>
4	#include <string.h>
5	
6	struct PushOverlap {
7	  PushOverlapOps ops;
8	  PushOverlapPush push;
9	  void *ctx;
10	  Canvas view;
11	  uint16_t *spare;
12	  uint16_t *newest; /* the buffer that holds the latest pushed frame */
13	  void *go, *done;
14	  bool busy, quit;
15	  int rows_result, rows_taken;
16	  uint32_t dur_result, last_us, credit_us;
17	};
18	
19	static void worker(void *arg) {
20	  PushOverlap *p = arg;
21	  for (;;) {
22	    p->ops.sem_take(p->go);
23	    if (p->quit) break;
24	    uint32_t t0 = p->ops.now_us();
25	    p->rows_result = p->push(p->ctx, &p->view);
26	    p->dur_result = p->ops.now_us() - t0;
27	    p->ops.sem_give(p->done);
28	  }
29	  p->ops.sem_give(p->done);
30	}
31	
32	static void release(PushOverlap *p) {
33	  if (p->ops.sem_destroy) {
34	    if (p->go) p->ops.sem_destroy(p->go);
35	    if (p->done) p->ops.sem_destroy(p->done);
36	  }
37	  free(p->view.dirty_x0);
38	  free(p->view.dirty_x1);
39	  free(p);
40	}
41	
42	PushOverlap *push_overlap_create(const Canvas *canvas, uint16_t *spare,
43	                                 const PushOverlapOps *ops, PushOverlapPush push,
44	                                 void *push_ctx) {
45	  if (!spare) return NULL;
46	  PushOverlap *p = calloc(1, sizeof *p);
47	  if (!p) return NULL;
48	  p->ops = *ops;
49	  p->push = push;
50	  p->ctx = push_ctx;
51	  p->spare = spare;
52	  p->view = *canvas;
53	  p->view.dirty_x0 = malloc((size_t)canvas->h * sizeof(int16_t));
54	  p->view.dirty_x1 = malloc((size_t)canvas->h * sizeof(int16_t));
55	  p->go = ops->sem_create();
56	  p->done = ops->sem_create();
57	  if (!p->view.dirty_x0 || !p->view.dirty_x1 || !p->go || !p->done ||
58	      ops->spawn(worker, p) != 0) {
59	    release(p);
60	    return NULL;
61	  }
62	  return p;
63	}
64	
65	void push_overlap_wait(PushOverlap *p) {
66	  if (!p->busy) return;
67	  p->ops.sem_take(p->done);
68	  p->busy = false;
69	  p->rows_taken += p->rows_result;
70	  p->last_us = p->dur_result;
71	}
72	
73	void push_overlap_reset(PushOverlap *p) {
74	  push_overlap_wait(p);
75	  p->newest = NULL;
76	}
77	
78	static bool any_dirty(const Canvas *c) {
79	  int x0, x1;
80	  for (int y = 0; y < c->h; y++)
81	    if (canvas_dirty_row(c, y, &x0, &x1)) return true;
82	  return false;
83	}
84	
85	bool push_overlap_present(PushOverlap *p, Canvas *canvas, bool eligible) {
86	  push_overlap_wait(p);
87	  if (eligible && any_dirty(canvas)) {
88	    memcpy(p->view.dirty_x0, canvas->dirty_x0,
89	           (size_t)canvas->h * sizeof(int16_t));
90	    memcpy(p->view.dirty_x1, canvas->dirty_x1,
91	           (size_t)canvas->h * sizeof(int16_t));
92	    canvas_clear_dirty(canvas);
93	    p->view.px = canvas->px;
94	    p->newest = canvas->px;
95	    canvas->px = p->spare;
96	    p->spare = p->newest;
97	    p->credit_us = p->last_us;
98	    p->busy = true;
99	    p->ops.sem_give(p->go);
100	    return true;
101	  }
102	  if (p->newest && p->newest != canvas->px) {
103	    p->spare = canvas->px;
104	    canvas->px = p->newest;
105	    canvas_clear_dirty(canvas);
106	  }
107	  p->newest = NULL;
108	  p->credit_us = 0;
109	  return false;
110	}
111	
112	uint32_t push_overlap_credit_us(const PushOverlap *p) { return p->credit_us; }
113	
114	int push_overlap_take_rows(PushOverlap *p) {
115	  int n = p->rows_taken;
116	  p->rows_taken = 0;
117	  return n;
118	}
119	
120	void push_overlap_destroy(PushOverlap *p) {
